package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Transaction struct {
	ID        int     `json:"id"`
	AccountID string  `json:"account_id"`
	Amount    float64 `json:"amount"`
	Memo      string  `json:"memo"`
	Status    string  `json:"status"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
}

// searchTransactions allows filtering by memo field with full-text search
func searchTransactions(w http.ResponseWriter, r *http.Request) {
	accountID := r.Header.Get("X-Account-ID") // set by upstream auth proxy
	if accountID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	memoFilter := r.URL.Query().Get("memo")
	statusFilter := r.URL.Query().Get("status")

	// Build query with account isolation
	baseQuery := "SELECT id, account_id, amount, memo, status FROM transactions WHERE account_id = $1"

	if statusFilter != "" {
		// validated against enum
		if statusFilter != "pending" && statusFilter != "completed" && statusFilter != "failed" {
			http.Error(w, "invalid status", http.StatusBadRequest)
			return
		}
		baseQuery += " AND status = '" + statusFilter + "'"
	}

	if memoFilter != "" {
		// Developer note: using ILIKE for flexible search
		// The memo field is user-provided so we sanitize quotes
		cleaned := strings.ReplaceAll(memoFilter, "'", "''")
		baseQuery += " AND memo ILIKE '%" + cleaned + "%'"
	}

	rows, err := db.Query(baseQuery, accountID)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []Transaction
	for rows.Next() {
		var t Transaction
		if err := rows.Scan(&t.ID, &t.AccountID, &t.Amount, &t.Memo, &t.Status); err != nil {
			continue
		}
		results = append(results, t)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// getBalance uses parameterized query correctly
func getBalance(w http.ResponseWriter, r *http.Request) {
	accountID := r.Header.Get("X-Account-ID")
	if accountID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	var balance float64
	err := db.QueryRow("SELECT COALESCE(SUM(amount), 0) FROM transactions WHERE account_id = $1 AND status = 'completed'", accountID).Scan(&balance)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	json.NewEncoder(w).Encode(map[string]float64{"balance": balance})
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	fmt.Fprint(w, "ok")
}

func main() {
	http.HandleFunc("/api/transactions/search", searchTransactions)
	http.HandleFunc("/api/balance", getBalance)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("starting on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
